class Library {
}

class User {
  + registration_date : date
  + security_deposit : double
  + phone : string
  + email : string
  + mail : string
}

class BorrowableItem {
  + library_code : string
  + location : string
}

class Book {
  + publisher : string
}

class MagazineIssue {
  + publication_date : date
  + publisher : string
}

class MusicCD {
  + publisher : string
  + artist : string
}

class Film {
  + duration : int
  + publisher : string
}

class Request {
}

class Actor {
}

class Author {
}

class Book extends BorrowableItem {}
class MagazineIssue extends BorrowableItem {}
class MusicCD extends BorrowableItem {}
class Film extends BorrowableItem {}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : has
Library "0..*" -- "0..*" BorrowableItem : request_to_retrieve

User "0..1" -- "0..3" BorrowableItem : borrows
User "1" -- "*" Request : makes
Request "0..*" -- "1" BorrowableItem : for

Book "*" -- "1..*" Author : written_by
Film "*" -- "1..*" Actor : features

@enduml

